using System;
using System.Drawing;
using System.Text;
using System.Windows.Forms;
namespace CircuitoStudio {
 public sealed class ProjectWizard:Form {
  readonly Project draft=new Project();readonly WizardSourceEditor sourceEditor; public Project Result;
  readonly Panel body=new Panel();readonly Label heading=new Label();readonly Button previous=new Button(),next=new Button(),cancel=new Button();readonly Panel[] pages=new Panel[3];int step;
  readonly TextBox name=new TextBox(),client=new TextBox(),site=new TextBox(),designer=new TextBox(),description1=new TextBox(),description2=new TextBox(),description3=new TextBox();readonly NumericUpDown frequency=new NumericUpDown(),circuits=new NumericUpDown(),power=new NumericUpDown();readonly ComboBox earth=new ComboBox(),phases=new ComboBox();readonly TextBox summary=new TextBox();
  public ProjectWizard(){Text="Novo projeto — alimentação e rede radial";ClientSize=new Size(700,600);MinimumSize=new Size(650,560);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);BackColor=Color.White;ShowInTaskbar=false;
   heading.Dock=DockStyle.Top;heading.Height=65;heading.Padding=new Padding(24,20,0,0);heading.Font=new Font(Font,FontStyle.Bold);Controls.Add(heading);
   Panel footer=new Panel{Dock=DockStyle.Bottom,Height=64,BackColor=Color.FromArgb(245,247,250)};FlowLayoutPanel buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(12),WrapContents=false};next.Text="Próximo >";previous.Text="< Voltar";cancel.Text="Cancelar";foreach(Button b in new[]{cancel,next,previous}){b.Width=115;b.Height=35;buttons.Controls.Add(b);}footer.Controls.Add(buttons);Controls.Add(footer);
   body.Dock=DockStyle.Fill;body.Padding=new Padding(24,8,24,8);Controls.Add(body);body.BringToFront();
   for(int i=0;i<3;i++){pages[i]=new Panel{Dock=DockStyle.Fill,AutoScroll=true};body.Controls.Add(pages[i]);}
   TableLayoutPanel data=Table();pages[0].Controls.Add(data);name.Text="Novo projeto";frequency.Minimum=1;frequency.Maximum=1000;frequency.Value=60;earth.DropDownStyle=ComboBoxStyle.DropDownList;earth.Items.AddRange(new object[]{"A definir","TT","TN-S","TN-C","IT"});earth.SelectedIndex=0;
   Field(data,"Nome do projeto",name);Field(data,"Cliente",client);Field(data,"Instalação / local",site);Field(data,"Responsável",designer);Field(data,"Descrição — linha 1",description1);Field(data,"Descrição — linha 2",description2);Field(data,"Descrição — linha 3",description3);Field(data,"Frequência (Hz)",frequency);Field(data,"Esquema de aterramento",earth);
   Label sourceNote=new Label{Dock=DockStyle.Top,Height=78,Text="Escolha rede BT/MT com transformador, gerador, fonte por R/X ou UPS. Fonte definida usa R/X por fase, N e PE separados; campo vazio significa desconhecido. UPS inversor e bypass são cenários distintos; não há transferência automática.",Padding=new Padding(0,0,0,8)};
   sourceEditor=new WizardSourceEditor(draft.Source);pages[1].Controls.Add(sourceEditor);pages[1].Controls.Add(sourceNote);
   TableLayoutPanel layout=Table();layout.Dock=DockStyle.Top;pages[2].Controls.Add(layout);circuits.Minimum=0;circuits.Maximum=12;circuits.Value=0;power.Minimum=0;power.Maximum=1000000;power.DecimalPlaces=2;power.Value=1;phases.DropDownStyle=ComboBoxStyle.DropDownList;phases.Items.AddRange(new object[]{"Monofásico (fase-neutro)","Trifásico equilibrado"});phases.SelectedIndex=0;
   Field(layout,"Circuitos iniciais (0 a 12)",circuits);Field(layout,"Tipo dos circuitos",phases);Field(layout,"Carga inicial por circuito (kW)",power);Label initial=new Label{Text="Valores iniciais editáveis: FP = 1 e demanda = 100%. Não representam dimensionamento. Cabos e proteções ficam sem seleção.",Dock=DockStyle.Top,Height=58};layout.Controls.Add(initial,0,layout.RowCount);layout.SetColumnSpan(initial,2);layout.RowCount++;
   summary.Multiline=true;summary.ReadOnly=true;summary.BorderStyle=BorderStyle.None;summary.BackColor=Color.White;summary.Height=180;summary.Dock=DockStyle.Top;layout.Controls.Add(summary,0,layout.RowCount);layout.SetColumnSpan(summary,2);layout.RowCount++;
   circuits.ValueChanged+=delegate{UpdateSummary();};power.ValueChanged+=delegate{UpdateSummary();};phases.SelectedIndexChanged+=delegate{UpdateSummary();};
   previous.Click+=delegate{if(step>0){step--;ShowStep();}};next.Click+=delegate{try{if(!CommitStep())return;if(step<2){step++;ShowStep();}else{BuildResult();Result.Validate();DialogResult=DialogResult.OK;Close();}}catch(Exception ex){Result=null;MessageBox.Show(this,ex.Message,"Confira os dados",MessageBoxButtons.OK,MessageBoxIcon.Information);}};cancel.Click+=delegate{Result=null;DialogResult=DialogResult.Cancel;Close();};CancelButton=cancel;AcceptButton=next;ShowStep();
  }
  static TableLayoutPanel Table(){return new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=2,ColumnStyles={new ColumnStyle(SizeType.Absolute,245),new ColumnStyle(SizeType.Percent,100)}};}
  static void Field(TableLayoutPanel t,string label,Control input){int row=t.RowCount++;t.RowStyles.Add(new RowStyle(SizeType.Absolute,48));t.Controls.Add(new Label{Text=label,AutoSize=true,Anchor=AnchorStyles.Left},0,row);input.Dock=DockStyle.Fill;input.Margin=new Padding(4,7,4,7);t.Controls.Add(input,1,row);}
  bool CommitStep(){if(step==0){if(String.IsNullOrWhiteSpace(name.Text)){MessageBox.Show(this,"Informe o nome do projeto.","Dados do projeto");name.Focus();return false;}draft.Name=name.Text.Trim();draft.Client=client.Text.Trim();draft.Site=site.Text.Trim();draft.Designer=designer.Text.Trim();draft.DescriptionLine1=description1.Text;draft.DescriptionLine2=description2.Text;draft.DescriptionLine3=description3.Text;draft.ValidateMetadata();draft.Frequency=(double)frequency.Value;draft.Earthing=earth.Text;}
   if(step==1){sourceEditor.Commit();if(Double.IsNaN(draft.Source.LineVoltage)||Double.IsInfinity(draft.Source.LineVoltage)||draft.Source.LineVoltage<1||draft.Source.LineVoltage>1000000)throw new InvalidOperationException("Informe tensão entre fases de 1 a 1000000 V.");if(draft.Source.Model==SourceModel.Rede&&draft.Source.LineVoltage>1000)throw new InvalidOperationException("Para rede MT no assistente, selecione base RedeMT e um transformador com saída BT até 1000 V. Gerador pode operar diretamente em MT.");draft.Validate();}return true;}
  void ShowStep(){for(int i=0;i<3;i++)pages[i].Visible=i==step;pages[step].BringToFront();heading.Text=(step+1)+" de 3 — "+new[]{"Dados do projeto","Alimentação e limites","Quadro inicial e revisão"}[step];previous.Enabled=step>0;next.Text=step==2?"Concluir":"Próximo >";UpdateSummary();}
  void UpdateSummary(){if(step!=2)return;double v=phases.SelectedIndex==1?draft.Source.LineVoltage:Math.Round(draft.Source.LineVoltage/Math.Sqrt(3),1);
   string source=draft.Source.Model==SourceModel.GeradorSincrono?"Gerador: "+draft.Source.GeneratorRatedKva+" kVA; xd''="+draft.Source.GeneratorXdPercent+"%; curto inicial simétrico":"Icc a montante: "+(draft.Source.ShortCircuitKA==0?"desconhecido":draft.Source.ShortCircuitKA+" kA; base "+draft.Source.CurrentBasis+(draft.Source.CurrentBasis==SourceCurrentBasis.RedeMT?" a "+draft.Source.UpstreamVoltageV+" V":" à tensão BT"));
   if(draft.Source.Model==SourceModel.ImpedanciaDefinida)source="Fonte equilibrada definida: R/X por fase="+draft.Source.DefinedPhaseROhm+" / "+draft.Source.DefinedPhaseXOhm+" Ω; N/PE separados";
   if(draft.Source.Model==SourceModel.UPS)source="UPS: "+draft.Source.UPSMode+"; "+draft.Source.UPSRatedKva+" kVA; limite declarado do inversor "+draft.Source.UPSCurrentLimitKA+" kA / "+draft.Source.UPSCurrentLimitSeconds+" s; sem transferência automática";
   summary.Text="Projeto: "+draft.Name+"\r\nCliente: "+draft.Client+"\r\nQuadro Q1: "+draft.Source.LineVoltage+" V entre fases\r\n"+circuits.Value+" circuito(s), "+v+" V, "+power.Value+" kW cada\r\nModelo: "+draft.Source.Model+"\r\n"+source+"\r\nUm único quadro na tensão da rede. Outros quadros poderão ser criados após concluir.";
  }
  void BuildResult(){draft.Boards.Clear();Board b=new Board{Id="Q1",Name="Quadro geral",Voltage=draft.Source.LineVoltage};for(int i=0;i<(int)circuits.Value;i++){bool three=phases.SelectedIndex==1;Circuit c=new Circuit{Id="C"+(i+1),Name="Circuito "+(i+1),Phases=three?PhaseMode.Trifasico:PhaseMode.Monofasico,PhaseLabel=three?"ABC":"L"+(i%3+1),Voltage=three?draft.Source.LineVoltage:Math.Round(draft.Source.LineVoltage/Math.Sqrt(3),1),PowerKw=(double)power.Value,PowerFactor=1,DemandFactor=1,CableMm2=0,BreakerA=0,LengthM=0};b.Circuits.Add(c);}draft.Boards.Add(b);Result=draft;}
 }
}
